ROW(10, '덤벨 바이셉스 컬', '팔꿈치를 굽혀 위팔 앞쪽 근육을 강화하는 운동입니다.', 'beginner', '팔', '덤벨', '양손에 덤벨을 들고 손바닥이 앞을 향하게 섭니다. 팔꿈치를 몸통 옆에 유지하면서 덤벨을 올린 뒤 천천히 내립니다.', '몸을 뒤로 젖히거나 팔꿈치를 앞뒤로 흔들지 마세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(11, '덤벨 해머 컬', '손바닥을 마주 보게 잡고 팔꿈치를 굽혀 위팔과 전완을 사용하는 운동입니다.', 'beginner', '팔', '덤벨', '덤벨을 몸 옆에 들고 손바닥을 몸 쪽으로 향하게 합니다. 손목을 곧게 유지하며 덤벨을 어깨 방향으로 올렸다가 천천히 내립니다.', '덤벨을 흔들어 올리지 말고 팔꿈치와 손목 위치를 안정적으로 유지하세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(12, '덤벨 트라이셉스 킥백', '팔꿈치를 펴서 위팔 뒤쪽 근육을 사용하는 운동입니다.', 'intermediate', '팔', '덤벨', '무릎을 약간 굽히고 고관절을 접어 상체를 기울입니다. 위팔을 몸통 옆에 고정하고 팔꿈치를 펴 덤벨을 뒤로 보낸 뒤 다시 굽힙니다.', '어깨를 흔들거나 허리를 둥글게 말지 말고 가벼운 무게로 수행하세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(13, '글루트 브리지', '누운 상태에서 골반을 들어 엉덩이 근육을 사용하는 운동입니다.', 'beginner', '엉덩이', '맨몸', '무릎을 세우고 누워 발을 골반너비로 둡니다. 발바닥으로 바닥을 누르며 골반을 들어 어깨부터 무릎까지 선을 맞춘 뒤 천천히 내립니다.', '허리를 과하게 젖히지 말고 무릎이 안쪽으로 모이지 않게 하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(14, '밴드 클램셸', '옆으로 누워 무릎을 벌리며 엉덩이 옆부분을 사용하는 운동입니다.', 'beginner', '엉덩이', '밴드', '루프 밴드를 무릎 위에 두고 옆으로 누워 고관절과 무릎을 굽힙니다. 발을 붙인 채 위쪽 무릎을 벌렸다가 천천히 닫습니다. 반대쪽도 반복합니다.', '골반이 뒤로 넘어가지 않도록 하고 허리 대신 엉덩이로 움직이세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(15, '밴드 사이드 워크', '옆으로 걸으며 엉덩이 옆 근육을 사용하는 운동입니다.', 'intermediate', '엉덩이', '밴드', '루프 밴드를 무릎 위에 두고 무릎과 고관절을 약간 굽힙니다. 발끝을 앞으로 둔 채 옆으로 한 걸음 이동하고 반대 발을 천천히 따라붙입니다. 양방향으로 반복합니다.', '무릎이 안으로 무너지거나 몸통이 좌우로 크게 흔들리지 않게 하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(16, '맨몸 스쿼트', '무릎과 고관절을 굽혔다 펴며 허벅지와 엉덩이를 사용하는 운동입니다.', 'beginner', '허벅지', '맨몸', '발을 어깨너비 정도로 벌립니다. 발바닥 전체로 바닥을 지지하며 엉덩이를 뒤로 보내 앉았다가 편안한 깊이에서 다시 일어섭니다.', '무릎이 발끝 방향을 따르게 하고 발뒤꿈치가 뜨거나 허리가 과도하게 말리지 않도록 하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(17, '리버스 런지', '한 발을 뒤로 내디뎌 허벅지와 엉덩이를 사용하는 운동입니다.', 'intermediate', '허벅지', '맨몸', '바르게 선 상태에서 한 발을 뒤로 내딛습니다. 양 무릎을 굽혀 몸을 낮춘 뒤 앞발로 바닥을 밀어 돌아옵니다. 좌우를 번갈아 수행합니다.', '앞무릎이 안쪽으로 꺾이지 않게 하고 균형을 유지할 수 있는 보폭으로 움직이세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(18, '덤벨 고블릿 스쿼트', '덤벨을 가슴 앞에 들고 앉았다 일어나 하체를 강화하는 운동입니다.', 'intermediate', '허벅지', '덤벨', '덤벨 하나를 양손으로 가슴 앞에 잡습니다. 발바닥 전체를 바닥에 유지하며 무릎과 고관절을 굽혀 내려갔다가 일어섭니다.', '덤벨을 몸에서 멀리 떼지 말고 무릎과 허리에 통증이 없는 깊이로 수행하세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(19, '스탠딩 카프 레이즈', '서서 발뒤꿈치를 들어 종아리 근육을 사용하는 운동입니다.', 'beginner', '종아리', '맨몸', '발을 골반너비로 벌리고 섭니다. 필요하면 벽에 손을 대고 발뒤꿈치를 천천히 올렸다가 바닥 가까이 내립니다.', '발목이 바깥이나 안쪽으로 꺾이지 않도록 하고 튀어 오르듯 반동을 쓰지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(20, '싱글 레그 카프 레이즈', '한쪽 다리로 발뒤꿈치를 들어 종아리와 균형 능력을 사용하는 운동입니다.', 'intermediate', '종아리', '맨몸', '벽에 손을 가볍게 대고 한 발로 섭니다. 지지하는 발의 뒤꿈치를 천천히 올렸다가 내립니다. 반대쪽도 반복합니다.', '균형이 어렵다면 양발 동작부터 시작하고 아킬레스건에 통증이 생기면 중단하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(21, '덤벨 카프 레이즈', '덤벨의 저항을 더해 종아리를 강화하는 운동입니다.', 'intermediate', '종아리', '덤벨', '양손에 가벼운 덤벨을 들고 발을 골반너비로 벌립니다. 발 앞부분으로 바닥을 누르며 뒤꿈치를 올린 뒤 천천히 내립니다.', '평평하고 미끄럽지 않은 바닥에서 수행하고 균형을 잃을 정도의 무게를 사용하지 마세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(22, '플랭크', '팔꿈치와 발끝으로 몸을 지지하며 복부를 사용하는 정적 운동입니다.', 'beginner', '복부', '맨몸', '팔꿈치를 어깨 아래에 두고 다리를 뻗습니다. 복부와 엉덩이에 힘을 주고 머리부터 발뒤꿈치까지 일직선을 유지하며 호흡합니다.', '허리가 처지거나 엉덩이가 과도하게 올라가지 않도록 하고 숨을 참지 마세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(23, '데드 버그', '누운 상태에서 팔다리를 교차로 움직이며 몸통을 안정시키는 운동입니다.', 'beginner', '복부', '맨몸', '누워 양팔을 천장으로 뻗고 고관절과 무릎을 굽힙니다. 반대쪽 팔과 다리를 천천히 뻗었다가 돌아오고 좌우를 번갈아 반복합니다.', '허리가 바닥에서 과도하게 뜨면 팔다리를 뻗는 범위를 줄이세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(24, '사이드 플랭크', '몸 옆면을 지지하며 복부 옆부분과 몸통 안정성을 사용하는 운동입니다.', 'intermediate', '복부', '맨몸', '옆으로 누워 팔꿈치를 어깨 아래에 둡니다. 다리를 뻗고 발 옆면과 아래팔로 바닥을 밀어 골반을 든 뒤 몸을 일직선으로 유지합니다. 양쪽을 수행합니다.', '어깨가 무너지지 않게 하고 어렵다면 무릎을 굽혀 바닥에 대고 수행하세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(25, '버드 도그', '네발기기 자세에서 팔다리를 교차로 뻗어 허리 주변과 몸통을 안정시키는 운동입니다.', 'beginner', '허리', '맨몸', '손을 어깨 아래, 무릎을 골반 아래에 둡니다. 한쪽 팔과 반대쪽 다리를 몸통 높이까지 뻗었다가 돌아옵니다. 좌우를 번갈아 수행합니다.', '골반을 비틀거나 허리를 젖히지 말고 몸통이 흔들리지 않는 범위로 뻗으세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(26, '맨몸 굿모닝', '고관절을 접는 동작을 연습하며 허리 주변과 하체 뒤쪽을 사용하는 운동입니다.', 'beginner', '허리', '맨몸', '발을 골반너비로 벌리고 무릎을 약간 굽힙니다. 척추의 자연스러운 곡선을 유지하며 엉덩이를 뒤로 보내 상체를 기울였다가 고관절을 펴 일어섭니다.', '허리를 구부려 숙이지 말고 허리에 통증이 없는 범위에서 천천히 움직이세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(27, '덤벨 루마니안 데드리프트', '고관절을 접고 펴며 하체 뒤쪽과 척추 주변 안정근을 사용하는 운동입니다.', 'intermediate', '허벅지', '덤벨', '덤벨을 허벅지 앞에 들고 무릎을 약간 굽힙니다. 덤벨을 다리 가까이 유지하며 엉덩이를 뒤로 보내 상체를 기울인 뒤 엉덩이에 힘을 주어 일어섭니다.', '허리를 둥글게 말거나 일어설 때 뒤로 젖히지 마세요. 덤벨을 바닥까지 내릴 필요는 없습니다.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(28, '제자리 걷기', '제자리에서 팔과 다리를 움직여 심박수를 서서히 높이는 운동입니다.', 'beginner', '유산소', '맨몸', '몸을 세우고 편안하게 섭니다. 양발을 번갈아 들며 자연스럽게 팔을 흔들고 일정한 리듬으로 걷습니다.', '미끄럽지 않은 바닥에서 시작하고 무릎을 무리하게 높이 들지 마세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(29, '점핑 잭', '팔과 다리를 벌렸다 모으며 전신을 사용하는 유산소 운동입니다.', 'intermediate', '유산소', '맨몸', '발을 모으고 선 뒤 가볍게 뛰면서 다리를 벌리고 팔을 머리 위로 올립니다. 다시 뛰어 발을 모으고 팔을 내려 반복합니다.', '무릎을 부드럽게 굽혀 착지하세요. 충격이 부담되면 점프 없이 한 발씩 옆으로 내딛으세요.', NULL, 'time', '["time","reps","time_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(30, '하이 니즈', '제자리에서 무릎을 번갈아 들어 올리는 달리기 동작입니다.', 'intermediate', '유산소', '맨몸', '몸을 세우고 팔을 달리듯 흔듭니다. 한쪽 무릎씩 편안한 높이로 빠르게 들어 올리며 제자리에서 달립니다.', '상체를 뒤로 젖히거나 발을 강하게 구르지 말고 통제 가능한 속도로 수행하세요.', NULL, 'time', '["time","reps","time_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(31, '벽 종아리 스트레칭', '벽을 지지하며 뒤쪽 다리의 종아리를 늘리는 스트레칭입니다.', 'beginner', '스트레칭', '맨몸', '벽에 양손을 대고 한 발을 뒤로 보냅니다. 뒷무릎을 펴고 뒤꿈치를 바닥에 유지한 채 앞무릎을 천천히 굽힙니다. 반대쪽도 반복합니다.', '발끝을 앞쪽으로 두고 반동 없이 편안한 당김까지만 늘리세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(32, '폼롤러 등 상부 이완', '폼롤러로 등 상부에 부드러운 압력을 가하는 자가 이완 동작입니다.', 'beginner', '등', '폼롤러', '폼롤러를 등 상부 아래에 가로로 두고 무릎을 세워 눕습니다. 손으로 머리를 지지하고 발로 바닥을 밀어 등 상부의 짧은 구간을 천천히 굴립니다.', '목과 허리 아래를 직접 굴리지 말고 척추나 갈비뼈에 강한 압력을 가하지 마세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(33, '마사지볼 엉덩이 이완', '마사지볼로 엉덩이 근육에 가벼운 압력을 가하는 자가 이완 동작입니다.', 'beginner', '엉덩이', '마사지볼', '벽과 한쪽 엉덩이 근육 사이에 마사지볼을 둡니다. 벽에 가볍게 기대어 압력을 조절하며 작은 범위로 천천히 움직입니다. 반대쪽도 수행합니다.', '뼈나 관절에 직접 압박하지 말고 저림이나 날카로운 통증이 생기면 중단하세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(34, '덤벨 벤트오버 로우', '상체를 기울인 상태에서 양손의 덤벨을 당겨 등을 사용하는 운동입니다.', 'intermediate', '등', '덤벨', '발을 골반너비로 두고 무릎을 약간 굽힌 뒤 고관절을 접습니다. 등을 곧게 유지하며 양쪽 팔꿈치를 골반 방향으로 당겼다가 덤벨을 천천히 내립니다.', '상체를 들썩이거나 허리를 둥글게 말지 마세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(35, '덤벨 레니게이드 로우', '플랭크 자세에서 덤벨을 번갈아 당겨 등과 몸통 안정근을 사용하는 운동입니다.', 'advanced', '등', '덤벨', '굴러가지 않는 육각 덤벨을 바닥에 두고 손잡이를 잡아 하이 플랭크를 만듭니다. 발을 넓게 벌리고 한쪽 덤벨을 몸통 옆으로 당겼다가 내려놓습니다. 양쪽을 교대로 수행합니다.', '원형 덤벨은 사용하지 마세요. 골반 회전과 허리 처짐을 줄이고 손목 통증이 있으면 중단하세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(36, '프론 Y 레이즈', '엎드린 자세에서 팔을 Y자로 들어 견갑골 주변을 사용하는 운동입니다.', 'beginner', '등', '맨몸', '이마를 바닥 가까이 두고 엎드려 팔을 Y자로 뻗습니다. 엄지를 천장 쪽으로 향하게 하고 팔을 바닥에서 조금 들었다가 내립니다.', '목을 뒤로 젖히거나 허리를 꺾어 팔을 높이 들지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(37, '프론 T 레이즈', '엎드려 팔을 옆으로 들어 등 상부와 뒤쪽 어깨를 사용하는 운동입니다.', 'beginner', '등', '맨몸', '엎드려 양팔을 어깨 높이에서 옆으로 뻗습니다. 목을 길게 유지하며 견갑골을 가볍게 모아 팔을 조금 들었다가 천천히 내립니다.', '어깨를 귀 쪽으로 올리지 말고 팔을 통증 없는 범위에서만 드세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(38, '리버스 스노 엔젤', '엎드린 상태에서 팔을 원호로 움직여 등 상부를 사용하는 운동입니다.', 'beginner', '등', '맨몸', '엎드려 팔을 몸 옆에 둡니다. 가슴은 낮게 유지하고 양손을 바닥에서 살짝 띄운 뒤 팔을 옆을 거쳐 머리 위 방향으로 이동했다가 돌아옵니다.', '허리를 젖히거나 어깨 관절을 억지로 돌리지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(39, '밴드 랫풀다운', '높은 곳에 고정한 밴드를 아래로 당겨 광배근을 사용하는 운동입니다.', 'beginner', '등', '밴드', '밴드를 운동용 고정점의 머리 위 높이에 고정합니다. 무릎을 꿇거나 서서 밴드를 잡고 팔꿈치를 몸통 양옆으로 당긴 뒤 천천히 팔을 폅니다.', '전용 고정점의 안전과 밴드 손상을 확인하고 얼굴 쪽으로 밴드를 놓지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(40, '밴드 스트레이트 암 풀다운', '팔꿈치를 거의 편 상태로 밴드를 내려 등 근육을 사용하는 운동입니다.', 'beginner', '등', '밴드', '밴드를 머리 위 운동용 고정점에 고정하고 양손으로 잡습니다. 무릎을 약간 굽히고 팔꿈치 각도를 유지한 채 손을 허벅지 쪽으로 내렸다가 돌아옵니다.', '허리를 젖히거나 팔꿈치를 크게 굽히지 말고 고정점이 풀리지 않는지 확인하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(41, '와이드 그립 풀업', '일반 풀업보다 약간 넓은 그립으로 몸을 당기는 운동입니다.', 'advanced', '등', '풀업바', '어깨너비보다 약간 넓게 바를 잡고 매달립니다. 몸통을 안정시킨 뒤 팔꿈치를 아래로 당겨 몸을 올리고 천천히 내려옵니다.', '손 간격을 과도하게 넓히지 말고 어깨 통증이 있으면 중단하세요. 바의 허용 하중을 확인하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(42, '스캐풀러 풀업', '팔꿈치를 편 채 견갑골을 움직여 매달린 몸을 조금 들어 올리는 운동입니다.', 'intermediate', '등', '풀업바', '바를 잡고 매달려 팔꿈치를 편 상태를 유지합니다. 어깨를 귀에서 멀리 내리며 몸을 조금 올린 뒤 천천히 시작 자세로 돌아옵니다.', '팔꿈치를 굽혀 일반 풀업으로 바꾸지 말고 반동이나 급격한 낙하를 피하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(43, '폼롤러 광배근 이완', '폼롤러로 옆구리 뒤쪽 광배근에 가벼운 압력을 주는 이완 동작입니다.', 'beginner', '등', '폼롤러', '옆으로 누워 아래쪽 팔을 머리 위로 뻗고 겨드랑이보다 아래의 등 바깥쪽에 폼롤러를 둡니다. 다리로 체중을 조절하며 짧게 천천히 움직입니다.', '겨드랑이 중심과 갈비뼈를 강하게 압박하지 말고 저림이 생기면 중단하세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(44, '마사지볼 등 상부 이완', '벽을 이용해 등 상부 근육을 부드럽게 압박하는 이완 동작입니다.', 'beginner', '등', '마사지볼', '벽과 견갑골 안쪽 근육 사이에 공을 놓습니다. 척추를 피한 위치에서 체중을 가볍게 싣고 작은 범위로 움직입니다. 좌우를 바꾸어 수행합니다.', '척추와 견갑골 뼈 위를 직접 누르지 말고 날카로운 통증이 생기면 멈추세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(45, '덤벨 스퀴즈 플로어 프레스', '덤벨을 서로 가볍게 누르며 밀어 가슴과 삼두근을 사용하는 운동입니다.', 'intermediate', '가슴', '덤벨', '무릎을 세우고 바닥에 누워 손바닥이 서로 마주 보도록 덤벨을 잡습니다. 덤벨을 가슴 앞에서 가볍게 맞댄 채 위로 밀고 천천히 내립니다.', '덤벨끼리 미끄러지거나 얼굴 쪽으로 이동하지 않게 하고 가벼운 중량을 사용하세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(46, '원암 덤벨 플로어 프레스', '한쪽 팔로 덤벨을 밀어 가슴과 몸통 안정근을 사용하는 운동입니다.', 'intermediate', '가슴', '덤벨', '무릎을 세우고 누워 한 손에 덤벨을 잡습니다. 몸통이 회전하지 않도록 복부에 힘을 주고 덤벨을 위로 밀었다가 위팔이 바닥에 가볍게 닿도록 내립니다. 반대쪽도 수행합니다.', '몸이 한쪽으로 기울지 않도록 하고 자유로운 손은 바닥에 두어 균형을 보조하세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(47, '니 푸시업', '무릎을 바닥에 대어 부하를 줄인 푸시업입니다.', 'beginner', '가슴', '맨몸', '손을 어깨너비보다 조금 넓게 짚고 무릎을 바닥에 댑니다. 머리부터 무릎까지 일직선을 유지하며 가슴을 낮춘 뒤 바닥을 밀어 올라옵니다.', '엉덩이만 뒤로 빼거나 허리를 꺾지 말고 손목이 아프면 중단하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(48, '밴드 체스트 프레스', '밴드의 저항을 이기며 팔을 앞으로 밀어 가슴을 사용하는 운동입니다.', 'beginner', '가슴', '밴드', '긴 밴드를 견갑골 아래 등 뒤로 두르고 양 끝을 잡습니다. 한 발을 앞에 두고 손을 가슴 양옆에서 앞으로 밀었다가 천천히 돌아옵니다.', '밴드를 목에 걸지 말고 손에서 미끄러지거나 끊어질 정도로 늘리지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(49, '밴드 체스트 플라이', '양팔을 앞쪽으로 모아 가슴 근육을 사용하는 운동입니다.', 'intermediate', '가슴', '밴드', '밴드를 뒤쪽 가슴 높이의 전용 고정점에 고정하고 양 끝을 잡습니다. 팔꿈치를 약간 굽힌 상태로 양팔을 가슴 앞에서 모았다가 편안한 범위로 벌립니다.', '어깨를 과도하게 뒤로 보내지 말고 고정점과 밴드의 상태를 확인하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(50, '밴드 푸시업', '등 뒤에 건 밴드로 저항을 더한 푸시업입니다.', 'advanced', '가슴', '밴드', '긴 밴드를 등 상부에 두르고 양 끝을 손바닥 아래에 고정해 푸시업 자세를 잡습니다. 몸을 일직선으로 유지하며 가슴을 낮췄다가 바닥을 밀어 올라옵니다.', '기본 푸시업을 안정적으로 할 수 있을 때 수행하세요. 밴드가 목 쪽으로 올라가지 않게 하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(51, '마사지볼 가슴 근육 이완', '벽과 마사지볼로 가슴 근육에 가벼운 압력을 주는 이완 동작입니다.', 'beginner', '가슴', '마사지볼', '벽과 한쪽 가슴의 근육 사이에 공을 놓고 몸을 살짝 기울입니다. 압력을 약하게 조절하며 작은 범위로 움직입니다. 반대쪽도 수행합니다.', '흉골과 쇄골, 겨드랑이와 유방 조직을 직접 압박하지 마세요. 팔 저림이 생기면 중단하세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(52, '덤벨 리버스 플라이', '상체를 기울이고 팔을 벌려 뒤쪽 어깨를 사용하는 운동입니다.', 'intermediate', '어깨', '덤벨', '무릎을 약간 굽히고 고관절을 접어 상체를 기울입니다. 가벼운 덤벨을 들고 팔꿈치를 약간 굽힌 채 양팔을 옆으로 벌렸다가 내립니다.', '덤벨을 반동으로 올리지 말고 목과 허리를 중립으로 유지하세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(53, '파이크 푸시업', '엉덩이를 높인 자세에서 몸을 밀어 어깨를 사용하는 운동입니다.', 'intermediate', '어깨', '맨몸', '손과 발을 바닥에 대고 엉덩이를 높여 역 V자 자세를 만듭니다. 팔꿈치를 굽혀 머리를 손 사이 앞쪽 바닥 가까이 낮춘 뒤 바닥을 밀어 올라옵니다.', '머리에 체중을 싣거나 목을 바닥에 누르지 마세요. 어깨와 손목이 아프면 중단하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(54, '스캐풀러 푸시업', '팔꿈치를 편 채 견갑골을 움직여 전거근과 어깨 안정근을 사용하는 운동입니다.', 'beginner', '어깨', '맨몸', '하이 플랭크에서 팔꿈치를 편 상태로 견갑골을 가볍게 모아 가슴을 조금 낮춥니다. 바닥을 밀어 견갑골을 벌리며 돌아옵니다. 어렵다면 무릎을 바닥에 댑니다.', '팔꿈치를 굽히거나 허리를 처뜨리지 말고 작은 범위로 움직이세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(55, '월 슬라이드', '벽을 따라 팔을 움직이며 어깨 움직임과 견갑골 조절을 연습하는 운동입니다.', 'beginner', '어깨', '맨몸', '벽을 바라보고 팔꿈치를 굽혀 아래팔을 벽에 댑니다. 어깨를 편안하게 유지하며 팔을 위로 미끄러뜨렸다가 내립니다.', '갈비뼈를 앞으로 내밀거나 허리를 젖히지 말고 통증 없는 높이까지만 올리세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(56, '밴드 외회전', '밴드 저항을 이용해 어깨 회전근을 사용하는 운동입니다.', 'beginner', '어깨', '밴드', '밴드를 팔꿈치 높이의 옆쪽 고정점에 고정합니다. 고정점에서 먼 손으로 잡고 팔꿈치를 몸통 옆에 붙여 직각으로 굽힌 뒤 아래팔을 바깥으로 돌렸다가 돌아옵니다.', '팔꿈치가 몸에서 떨어지거나 몸통이 회전하지 않게 하고 약한 저항부터 사용하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(57, '밴드 숄더 프레스', '밴드의 저항을 이기며 팔을 위로 밀어 어깨를 사용하는 운동입니다.', 'intermediate', '어깨', '밴드', '긴 밴드 중앙을 양발로 밟고 양 끝을 어깨 높이에서 잡습니다. 복부에 힘을 주어 손을 머리 위로 밀고 천천히 내립니다.', '밴드가 발에서 빠지지 않게 하고 허리를 젖히지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(58, '마사지볼 후면 어깨 이완', '벽을 지지하여 어깨 뒤쪽 근육에 가벼운 압력을 주는 이완 동작입니다.', 'beginner', '어깨', '마사지볼', '벽과 어깨 뒤쪽 근육 사이에 마사지볼을 놓습니다. 체중을 약하게 싣고 공을 작은 범위로 움직인 뒤 반대쪽도 수행합니다.', '어깨 관절과 견갑골 뼈 위를 누르지 말고 팔이 저리면 바로 중단하세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(59, '클로즈 그립 푸시업', '손 간격을 좁혀 삼두근의 기여를 높인 푸시업입니다.', 'intermediate', '팔', '맨몸', '손을 어깨너비 정도 또는 그보다 조금 좁게 둡니다. 몸을 일직선으로 유지하며 팔꿈치를 몸통 가까이 굽혀 내려갔다가 바닥을 밀어 올라옵니다.', '손을 무리하게 붙이지 말고 팔꿈치와 손목에 통증이 없는 간격을 사용하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(60, '다이아몬드 푸시업', '엄지와 검지가 마름모 모양이 되도록 손을 두는 푸시업 변형입니다.', 'advanced', '팔', '맨몸', '하이 플랭크 자세에서 가슴 아래에 양손을 가까이 두어 엄지와 검지로 마름모 모양을 만듭니다. 팔꿈치를 굽혀 몸을 낮추고 다시 밀어 올립니다.', '손목 부담이 크면 손 간격을 넓힌 클로즈 그립 푸시업으로 바꾸세요. 허리를 꺾지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(61, '스핑크스 푸시업', '아래팔 지지 자세에서 팔꿈치를 펴며 삼두근을 사용하는 운동입니다.', 'advanced', '팔', '맨몸', '팔꿈치를 어깨보다 약간 앞에 두어 아래팔 플랭크를 만듭니다. 손바닥으로 바닥을 밀며 두 팔꿈치를 펴고 천천히 다시 아래팔을 내립니다.', '팔꿈치를 바닥에 떨어뜨리지 말고 어렵다면 무릎을 바닥에 대세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(62, '밴드 바이셉스 컬', '밴드를 당겨 위팔 앞쪽 근육을 사용하는 운동입니다.', 'beginner', '팔', '밴드', '긴 밴드 중앙을 발로 밟고 양 끝을 손바닥이 앞을 향하게 잡습니다. 팔꿈치를 몸통 옆에 고정해 손을 어깨 쪽으로 올렸다가 내립니다.', '밴드가 발에서 빠지지 않게 하고 몸통을 흔들지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(63, '밴드 트라이셉스 푸시다운', '높게 고정한 밴드를 아래로 밀며 삼두근을 사용하는 운동입니다.', 'beginner', '팔', '밴드', '밴드를 머리 위 전용 고정점에 고정합니다. 팔꿈치를 몸통 옆에 붙이고 밴드를 잡은 손을 아래로 내려 팔꿈치를 폈다가 천천히 굽힙니다.', '어깨를 앞뒤로 흔들거나 밴드를 놓지 마세요. 고정 상태를 확인하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(64, '밴드 오버헤드 트라이셉스 익스텐션', '머리 위에서 팔꿈치를 펴며 삼두근을 사용하는 운동입니다.', 'intermediate', '팔', '밴드', '긴 밴드 한쪽을 뒤쪽 발로 밟고 다른 쪽을 양손으로 잡아 머리 뒤에 둡니다. 위팔 위치를 유지한 채 팔꿈치를 펴 손을 위로 올렸다가 돌아옵니다.', '밴드가 발에서 빠지지 않게 하고 목을 앞으로 내밀거나 허리를 젖히지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(65, '친업', '손바닥이 몸을 향하는 그립으로 몸을 당겨 위팔 앞쪽과 등을 사용하는 운동입니다.', 'advanced', '팔', '풀업바', '바를 어깨너비 정도의 언더핸드 그립으로 잡고 매달립니다. 몸을 흔들지 않고 팔꿈치를 굽혀 턱을 바 높이까지 올린 뒤 천천히 내려옵니다.', '손목과 팔꿈치가 아프면 중단하고 바의 고정 상태를 확인하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(66, '싱글 레그 글루트 브리지', '한쪽 다리로 골반을 들어 엉덩이를 사용하는 운동입니다.', 'intermediate', '엉덩이', '맨몸', '무릎을 세우고 누워 한쪽 다리를 바닥에서 듭니다. 지지하는 발로 바닥을 눌러 골반을 올렸다가 내립니다. 좌우를 바꾸어 반복합니다.', '골반이 기울거나 허리가 과도하게 젖혀지지 않도록 하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(67, '사이드 라잉 힙 어브덕션', '옆으로 누워 위쪽 다리를 들어 엉덩이 옆 근육을 사용하는 운동입니다.', 'beginner', '엉덩이', '맨몸', '옆으로 누워 아래쪽 무릎을 굽혀 몸을 지지합니다. 위쪽 다리를 곧게 뻗고 발끝이 정면을 향하도록 유지하며 다리를 옆으로 들었다가 내립니다.', '골반을 뒤로 넘기거나 다리를 과도하게 높이 들지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(68, '덤벨 글루트 브리지', '골반 위에 덤벨을 얹고 엉덩이를 들어 올리는 운동입니다.', 'intermediate', '엉덩이', '덤벨', '무릎을 세우고 누워 덤벨을 골반 앞쪽의 접히는 부위에 안전하게 올리고 양손으로 고정합니다. 발로 바닥을 눌러 골반을 올렸다가 내립니다.', '복부를 직접 누르지 말고 덤벨이 굴러가지 않게 잡으세요. 허리를 꺾지 마세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(69, '덤벨 스모 스쿼트', '넓은 발 간격으로 앉았다 일어나 엉덩이와 허벅지 안쪽을 사용하는 운동입니다.', 'intermediate', '엉덩이', '덤벨', '발을 어깨보다 넓게 벌리고 발끝을 편안하게 바깥으로 향하게 합니다. 덤벨을 양손으로 몸 앞에 잡고 무릎이 발끝 방향을 따르게 내려갔다가 일어섭니다.', '발 간격을 과도하게 넓히지 말고 허리가 말리지 않는 깊이로 수행하세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(70, '덤벨 싱글 레그 루마니안 데드리프트', '한쪽 다리로 균형을 잡고 고관절을 접어 엉덩이와 허벅지 뒤쪽을 사용하는 운동입니다.', 'advanced', '엉덩이', '덤벨', '한 손에 가벼운 덤벨을 들고 반대 다리로 섭니다. 지지하는 무릎을 약간 굽힌 채 엉덩이를 뒤로 보내고 반대 다리를 뒤로 뻗으며 상체를 기울였다가 돌아옵니다.', '골반을 옆으로 열거나 허리를 둥글게 말지 마세요. 균형이 불안하면 중단하세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(71, '밴드 글루트 브리지', '무릎 위 밴드의 저항을 유지하며 골반을 드는 운동입니다.', 'beginner', '엉덩이', '밴드', '루프 밴드를 무릎 위에 두고 무릎을 세워 눕습니다. 무릎 간격을 유지하며 발바닥으로 바닥을 눌러 골반을 올렸다가 내립니다.', '무릎이 안쪽으로 모이거나 허리가 과도하게 젖혀지지 않도록 하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(72, '폼롤러 둔근 이완', '폼롤러 위에 앉아 엉덩이 근육에 부드러운 압력을 주는 이완 동작입니다.', 'beginner', '엉덩이', '폼롤러', '폼롤러에 앉아 양손을 뒤쪽 바닥에 짚습니다. 한쪽 엉덩이로 체중을 조금 옮겨 짧은 범위를 천천히 굴리고 반대쪽도 수행합니다.', '꼬리뼈를 누르거나 체중을 과도하게 싣지 마세요. 다리 저림이 있으면 중단하세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(73, '맨몸 스플릿 스쿼트', '앞뒤로 벌린 발을 유지하며 무릎을 굽혔다 펴는 하체 운동입니다.', 'beginner', '허벅지', '맨몸', '한 발을 앞으로, 한 발을 뒤로 두고 섭니다. 몸을 수직으로 낮추며 양 무릎을 굽힌 뒤 앞발로 바닥을 밀어 올라옵니다. 좌우를 바꾸어 수행합니다.', '발을 외줄처럼 일직선으로 두지 말고 앞무릎이 안으로 꺾이지 않게 하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(74, '덤벨 리버스 런지', '덤벨을 들고 뒤로 내딛으며 허벅지와 엉덩이를 사용하는 운동입니다.', 'intermediate', '허벅지', '덤벨', '양손에 덤벨을 몸 옆으로 들고 섭니다. 한 발을 뒤로 내디뎌 양 무릎을 굽힌 뒤 앞발로 바닥을 밀어 돌아옵니다. 좌우를 번갈아 수행합니다.', '몸통을 과도하게 기울이지 말고 균형을 유지할 수 있는 무게를 선택하세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(75, '밴드 스쿼트', '긴 밴드의 저항을 더한 스쿼트입니다.', 'beginner', '허벅지', '밴드', '긴 밴드 중앙을 양발로 밟고 양 끝을 어깨 옆에서 잡습니다. 발바닥 전체를 지지하며 앉았다가 밴드를 늘리면서 일어섭니다.', '밴드를 목에 걸지 말고 발에서 빠지지 않도록 하세요. 무릎은 발끝 방향을 따르게 하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(76, '밴드 레그 익스텐션', '앉은 자세에서 밴드에 저항하며 무릎을 펴는 운동입니다.', 'beginner', '허벅지', '밴드', '움직이지 않는 의자에 앉아 한쪽 발목의 밴드를 뒤쪽 낮은 전용 고정점에 연결합니다. 허벅지는 의자에 유지하고 무릎을 천천히 폈다가 돌아옵니다. 좌우를 바꿉니다.', '의자와 밴드 고정 상태를 확인하고 무릎을 튕기듯 잠그지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(77, '밴드 라잉 레그 컬', '엎드린 자세에서 밴드에 저항하며 무릎을 굽히는 운동입니다.', 'beginner', '허벅지', '밴드', '밴드 한쪽을 발쪽의 낮은 전용 고정점에 고정하고 다른 쪽을 한쪽 발목에 안전하게 연결한 뒤 엎드립니다. 골반을 바닥에 유지하며 뒤꿈치를 엉덩이 방향으로 당겼다가 천천히 폅니다.', '발목 고정에 적합한 밴드를 쓰고 허리를 젖히거나 골반을 들지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(78, '폼롤러 대퇴사두근 이완', '폼롤러로 허벅지 앞쪽에 부드러운 압력을 주는 이완 동작입니다.', 'beginner', '허벅지', '폼롤러', '엎드려 아래팔로 상체를 받치고 허벅지 앞쪽 아래에 폼롤러를 둡니다. 팔과 반대쪽 다리로 체중을 조절하며 짧게 굴립니다.', '무릎뼈와 골반뼈를 직접 굴리지 말고 허리를 과도하게 젖히지 마세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(79, '폼롤러 햄스트링 이완', '앉은 상태에서 허벅지 뒤쪽을 부드럽게 굴리는 이완 동작입니다.', 'beginner', '허벅지', '폼롤러', '바닥에 앉아 한쪽 허벅지 뒤에 폼롤러를 둡니다. 양손을 뒤에 짚고 체중을 조절하며 엉덩이 아래부터 무릎 뒤를 제외한 구간을 천천히 굴립니다.', '무릎 뒤 오금과 좌골을 직접 누르지 말고 저림이 생기면 중단하세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(80, '폼롤러 내전근 이완', '폼롤러로 허벅지 안쪽 근육에 가벼운 압력을 주는 이완 동작입니다.', 'beginner', '허벅지', '폼롤러', '엎드려 한쪽 무릎을 옆으로 굽히고 허벅지 안쪽 아래에 폼롤러를 둡니다. 아래팔로 체중을 지지하며 허벅지 중간의 짧은 구간을 천천히 굴립니다.', '사타구니와 무릎 안쪽을 직접 누르지 말고 압력을 약하게 시작하세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(81, '벤트 니 카프 레이즈', '무릎을 약간 굽힌 채 뒤꿈치를 들어 종아리를 사용하는 운동입니다.', 'beginner', '종아리', '맨몸', '벽에 손을 가볍게 대고 양 무릎을 조금 굽힙니다. 무릎 각도를 유지한 채 발뒤꿈치를 들었다가 천천히 내립니다.', '발목이 좌우로 무너지지 않게 하고 반동으로 뛰지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(82, '덤벨 시티드 카프 레이즈', '앉아서 무릎 위의 덤벨에 저항하며 종아리를 사용하는 운동입니다.', 'beginner', '종아리', '덤벨', '안정된 의자에 앉아 무릎을 직각 정도로 굽힙니다. 덤벨을 무릎뼈보다 몸 쪽의 허벅지 위에 두고 손으로 고정한 뒤 발뒤꿈치를 올렸다가 내립니다.', '무릎뼈를 직접 누르지 말고 덤벨이 굴러가지 않게 잡으세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(83, '덤벨 싱글 레그 카프 레이즈', '덤벨의 저항을 더해 한쪽 종아리로 뒤꿈치를 드는 운동입니다.', 'intermediate', '종아리', '덤벨', '한 손에 가벼운 덤벨을 들고 다른 손으로 벽을 가볍게 지지합니다. 한 발로 서서 뒤꿈치를 천천히 올렸다가 내리고 반대쪽도 수행합니다.', '체중과 덤벨을 통제할 수 있을 때 수행하고 아킬레스건 통증이 생기면 중단하세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(84, '밴드 발목 저측굴곡', '밴드에 저항해 발끝을 앞으로 밀며 종아리를 사용하는 운동입니다.', 'beginner', '종아리', '밴드', '바닥에 앉아 한쪽 다리를 뻗고 발 앞부분에 긴 밴드를 걸어 양 끝을 잡습니다. 발목을 움직여 발끝을 몸에서 멀리 밀었다가 천천히 돌아옵니다.', '밴드가 발끝에서 빠져 얼굴 쪽으로 튀지 않게 하고 발가락만 구부리지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(85, '폼롤러 종아리 이완', '폼롤러로 종아리 뒤쪽에 가벼운 압력을 주는 이완 동작입니다.', 'beginner', '종아리', '폼롤러', '앉아서 한쪽 종아리 아래에 폼롤러를 둡니다. 양손과 반대 발로 체중을 조절하며 종아리 근육 구간을 천천히 굴립니다.', '아킬레스건과 오금은 직접 누르지 마세요. 붓거나 열감이 있는 부위는 압박하지 마세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(86, '마사지볼 종아리 이완', '작은 공으로 종아리 근육을 부드럽게 압박하는 이완 동작입니다.', 'beginner', '종아리', '마사지볼', '바닥에 앉아 종아리 근육 아래에 마사지볼을 둡니다. 다리에 실리는 무게를 손으로 조절하고 작은 범위로 천천히 움직입니다.', '단단한 공에 체중을 과하게 싣거나 오금과 아킬레스건을 직접 누르지 마세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(87, '덤벨 수트케이스 캐리', '한쪽 손에 덤벨을 들고 걸으며 몸통이 옆으로 기울지 않도록 버티는 운동입니다.', 'intermediate', '복부', '덤벨', '한 손에 덤벨을 들고 몸을 곧게 세웁니다. 양어깨 높이를 유지한 채 짧은 보폭으로 걷고 방향을 바꾸어 돌아옵니다. 손을 바꾸어 수행합니다.', '덤벨 쪽으로 몸을 기울이거나 어깨를 으쓱하지 말고 이동 공간을 확보하세요.', NULL, 'weight_time', '["weight_time","time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(88, '덤벨 데드 버그', '덤벨을 고정해 든 상태에서 다리를 교차로 뻗으며 몸통을 안정시키는 운동입니다.', 'intermediate', '복부', '덤벨', '누워 가벼운 덤벨 하나를 양손으로 안전하게 잡아 가슴 위에 둡니다. 무릎과 고관절을 굽힌 상태에서 한쪽 다리를 천천히 뻗었다가 돌아옵니다. 좌우를 번갈아 수행합니다.', '덤벨을 얼굴 위에 두지 말고 허리가 과도하게 뜨면 다리의 이동 범위를 줄이세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(89, '덤벨 우드초퍼', '덤벨을 대각선으로 옮기며 몸통 회전을 조절하는 운동입니다.', 'intermediate', '복부', '덤벨', '가벼운 덤벨 하나를 양손으로 잡고 한쪽 골반 옆에 둡니다. 발과 고관절을 함께 돌려 반대쪽 어깨 높이 방향으로 옮겼다가 천천히 돌아옵니다. 반대 방향도 수행합니다.', '허리만 비틀지 말고 무릎과 발끝이 함께 회전하게 하세요. 무거운 덤벨을 휘두르지 마세요.', NULL, 'weight_reps', '["weight_reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(90, '밴드 팔로프 프레스', '옆에서 당기는 밴드에 저항해 몸통 회전을 억제하는 운동입니다.', 'beginner', '복부', '밴드', '밴드를 가슴 높이 전용 고정점에 고정하고 고정점이 옆에 오도록 섭니다. 양손으로 밴드를 가슴 앞에 잡고 팔을 앞으로 뻗었다가 돌아옵니다. 방향을 바꾸어 반복합니다.', '몸통이 고정점 쪽으로 돌아가지 않게 하고 밴드의 장력을 낮게 시작하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(91, '밴드 우드초퍼', '높은 곳의 밴드를 대각선으로 당기며 몸통 회전을 조절하는 운동입니다.', 'intermediate', '복부', '밴드', '밴드를 어깨보다 높은 전용 고정점에 고정합니다. 옆으로 서서 양손으로 잡고 발과 고관절을 함께 돌리며 반대쪽 골반 방향으로 당겼다가 돌아옵니다. 양쪽을 수행합니다.', '발을 고정한 채 허리만 비틀지 말고 밴드를 놓아 튕기지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(92, '밴드 스탠딩 크런치', '높게 고정한 밴드에 저항하며 몸통을 짧게 굽히는 운동입니다.', 'intermediate', '복부', '밴드', '머리 위 전용 고정점에 밴드를 고정하고 양 끝을 어깨 옆에서 잡습니다. 무릎을 약간 굽히고 갈비뼈를 골반 쪽으로 가까이 하며 몸통을 조금 굽혔다가 돌아옵니다.', '목을 잡아당기거나 밴드에 목을 걸지 말고 고관절만 접는 동작이 되지 않게 하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(93, '행잉 니 레이즈', '바에 매달려 무릎을 올리며 복부와 고관절 굴곡근을 사용하는 운동입니다.', 'intermediate', '복부', '풀업바', '바를 잡고 어깨를 안정시켜 매달립니다. 몸이 흔들리지 않도록 무릎을 굽혀 골반 쪽으로 올리고 천천히 내립니다.', '반동을 쓰거나 허리를 과하게 젖히지 마세요. 악력이 풀리기 전에 내려오세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(94, '행잉 레그 레이즈', '바에 매달려 다리를 편 채 들어 올리는 복부 운동입니다.', 'advanced', '복부', '풀업바', '바에 안정적으로 매달리고 무릎을 가능한 범위에서 편 상태로 다리를 앞으로 들어 올립니다. 몸통의 흔들림을 억제하며 천천히 다리를 내립니다.', '무릎을 억지로 잠그지 말고 행잉 니 레이즈를 통제할 수 있을 때 진행하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(95, '행잉 오블리크 니 레이즈', '매달린 상태에서 무릎을 대각선으로 올려 복부 옆부분을 사용하는 운동입니다.', 'advanced', '복부', '풀업바', '바에 안정적으로 매달립니다. 무릎을 굽혀 한쪽 골반 방향으로 올렸다가 천천히 내리고 반대쪽으로 반복합니다.', '허리를 과도하게 비틀거나 몸을 흔들지 말고 작은 범위부터 시작하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(96, '프론 얼터네이팅 암 레그 레이즈', '엎드려 반대쪽 팔과 다리를 조금 들어 척추 주변 안정근을 사용하는 운동입니다.', 'beginner', '허리', '맨몸', '엎드려 양팔을 앞에 뻗고 목을 중립으로 둡니다. 한쪽 팔과 반대쪽 다리를 바닥에서 조금 들었다가 내리고 좌우를 번갈아 수행합니다.', '팔다리를 높이 들기 위해 허리를 꺾지 말고 통증 없는 작은 범위로 수행하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(97, '밴드 굿모닝', '고관절을 접는 동안 밴드 저항에 맞서 몸통을 안정시키는 운동입니다.', 'intermediate', '허리', '밴드', '긴 루프 밴드 아래쪽을 양발로 밟고 위쪽을 목이 아닌 등 상부에 둡니다. 무릎을 조금 굽히고 엉덩이를 뒤로 보내 상체를 기울였다가 일어섭니다.', '밴드를 목에 걸지 마세요. 허리 운동 범위를 늘리기보다 고관절을 접고 펴며 척추는 중립으로 유지하세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(98, '차일드 포즈', '엉덩이를 뒤로 보내며 등과 어깨를 편안하게 늘리는 스트레칭입니다.', 'beginner', '스트레칭', '맨몸', '무릎을 꿇고 손을 앞으로 뻗습니다. 엉덩이를 발뒤꿈치 방향으로 천천히 보내고 편안한 범위에서 호흡합니다.', '무릎과 고관절이 아프면 범위를 줄이고 엉덩이를 억지로 발뒤꿈치에 붙이지 마세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(99, '누운 둔근 스트레칭', '누운 상태에서 다리를 교차하여 엉덩이 근육을 늘리는 스트레칭입니다.', 'beginner', '스트레칭', '맨몸', '무릎을 세우고 누워 한쪽 발목을 반대쪽 허벅지 위에 올립니다. 아래쪽 허벅지 뒤를 잡고 몸 쪽으로 가볍게 당긴 뒤 반대쪽도 수행합니다.', '위쪽 무릎을 손으로 강하게 누르지 말고 저림이나 관절 통증이 생기면 멈추세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(100, '밴드 햄스트링 스트레칭', '밴드를 보조로 사용해 누운 상태에서 허벅지 뒤쪽을 늘리는 스트레칭입니다.', 'beginner', '스트레칭', '밴드', '누워 한쪽 발바닥에 긴 밴드를 걸고 양 끝을 잡습니다. 무릎을 약간 굽힌 채 다리를 들어 허벅지 뒤에 가벼운 당김이 느껴지는 지점에서 유지합니다. 양쪽을 수행합니다.', '밴드로 다리를 강하게 당기지 말고 허리가 바닥에서 크게 뜨거나 발이 저리면 범위를 줄이세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(101, '밴드 종아리 스트레칭', '밴드로 발 앞부분을 가볍게 당겨 종아리를 늘리는 스트레칭입니다.', 'beginner', '스트레칭', '밴드', '바닥에 앉아 한쪽 다리를 뻗고 발 앞부분에 긴 밴드를 걸어 잡습니다. 발끝을 몸 쪽으로 부드럽게 당겨 유지한 뒤 반대쪽도 수행합니다.', '밴드가 발에서 빠지지 않게 하고 발가락만 강하게 젖히지 마세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(102, '밴드 어깨 패스스루', '긴 밴드를 넓게 잡고 팔을 앞에서 뒤로 이동하는 어깨 가동성 운동입니다.', 'intermediate', '스트레칭', '밴드', '긴 밴드를 넓게 잡아 허벅지 앞에 둡니다. 팔꿈치를 편안하게 유지하고 양팔을 머리 위로 올린 뒤 통증 없는 경우에만 몸 뒤쪽으로 조금 이동했다가 돌아옵니다.', '손 간격을 충분히 넓게 잡고 어깨가 걸리거나 아프면 뒤로 넘기지 마세요. 허리를 젖히지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(103, '폼롤러 흉추 신전', '폼롤러를 지지점으로 사용해 등 상부를 부드럽게 펴는 가동성 운동입니다.', 'beginner', '스트레칭', '폼롤러', '무릎을 세우고 누워 등 상부에 폼롤러를 가로로 둡니다. 양손으로 머리를 받치고 엉덩이를 바닥에 유지하며 등 상부를 조금 폈다가 돌아옵니다.', '허리 아래에 폼롤러를 두지 말고 목을 꺾거나 머리를 뒤로 떨어뜨리지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(104, '폼롤러 스노 엔젤', '폼롤러 위에 길게 누워 팔을 움직이며 가슴과 어깨를 여는 가동성 운동입니다.', 'beginner', '스트레칭', '폼롤러', '머리부터 골반까지 지지할 수 있는 긴 폼롤러를 등뼈 방향으로 두고 눕습니다. 발을 넓게 두어 균형을 잡고 양팔을 옆으로 벌려 머리 위 방향으로 천천히 이동했다가 돌아옵니다.', '짧은 폼롤러로 머리가 지지되지 않으면 수행하지 마세요. 팔을 바닥에 억지로 누르지 마세요.', NULL, 'reps', '["reps"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00'),
ROW(105, '마사지볼 발바닥 이완', '마사지볼을 발바닥 아래에서 굴리는 자가 이완 동작입니다.', 'beginner', '스트레칭', '마사지볼', '안정된 의자에 앉아 한쪽 발바닥 아래에 마사지볼을 둡니다. 발로 가볍게 눌러 발바닥의 근육 구간을 천천히 굴린 뒤 반대 발도 수행합니다.', '단단한 공에 체중을 과하게 싣지 말고 통증이 있는 발뒤꿈치를 직접 강하게 누르지 마세요.', NULL, 'time', '["time"]', '2026-11-12 09:00:00', '2026-11-12 15:00:00')
) AS new (exercise_id, name, instructions, difficulty, exercise_type, exercise_equipment, description, cautions, source_url, default_record_mode, allowed_record_modes, created_at, updated_at)
WHERE @seed_blocked = 0 AND NOT EXISTS (SELECT 1 FROM seed_exercise_conflicts)
ON DUPLICATE KEY UPDATE name = new.name, instructions = new.instructions, difficulty = new.difficulty, exercise_type = new.exercise_type, exercise_equipment = new.exercise_equipment, description = new.description, cautions = new.cautions, source_url = new.source_url, default_record_mode = new.default_record_mode, allowed_record_modes = new.allowed_record_modes, created_at = new.created_at, updated_at = new.updated_at;

DROP TEMPORARY TABLE seed_exercise_conflicts;
DROP TEMPORARY TABLE seed_exercise_names;
